const bundle = {
  "package.json": "{\n  \"name\": \"react-example\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite --port=3000 --host=0.0.0.0\",\n    \"build\": \"vite build\",\n    \"preview\": \"vite preview\",\n    \"clean\": \"rm -rf dist server.js\",\n    \"lint\": \"tsc --noEmit\"\n  },\n  \"dependencies\": {\n    \"@google/genai\": \"^2.4.0\",\n    \"@tailwindcss/vite\": \"^4.1.14\",\n    \"@vitejs/plugin-react\": \"^5.0.4\",\n    \"dotenv\": \"^17.2.3\",\n    \"express\": \"^4.21.2\",\n    \"lucide-react\": \"^0.546.0\",\n    \"motion\": \"^12.23.24\",\n    \"pixi.js\": \"^8.19.0\",\n    \"react\": \"^19.0.1\",\n    \"react-dom\": \"^19.0.1\",\n    \"vite\": \"^6.2.3\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.14.0\",\n    \"autoprefixer\": \"^10.4.21\",\n    \"esbuild\": \"^0.25.0\",\n    \"tailwindcss\": \"^4.1.14\",\n    \"tsx\": \"^4.21.0\",\n    \"typescript\": \"~5.8.2\",\n    \"vite\": \"^6.2.3\",\n    \"@types/express\": \"^4.17.21\"\n  }\n}\n",
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"experimentalDecorators\": true,\n    \"useDefineForClassFields\": false,\n    \"module\": \"ESNext\",\n    \"lib\": [\n      \"ES2022\",\n      \"DOM\",\n      \"DOM.Iterable\"\n    ],\n    \"skipLibCheck\": true,\n    \"moduleResolution\": \"bundler\",\n    \"isolatedModules\": true,\n    \"moduleDetection\": \"force\",\n    \"allowJs\": true,\n    \"jsx\": \"react-jsx\",\n    \"paths\": {\n      \"@/*\": [\n        \"./*\"\n      ]\n    },\n    \"allowImportingTsExtensions\": true,\n    \"noEmit\": true\n  }\n}\n",
  "vite.config.ts": "import tailwindcss from '@tailwindcss/vite';\nimport react from '@vitejs/plugin-react';\nimport path from 'path';\nimport {defineConfig} from 'vite';\n\nexport default defineConfig(() => {\n  return {\n    plugins: [react(), tailwindcss()],\n    resolve: {\n      alias: {\n        '@': path.resolve(__dirname, '.'),\n      },\n    },\n    server: {\n      // HMR is disabled in AI Studio via DISABLE_HMR env var.\n      // Do not modifyâfile watching is disabled to prevent flickering during agent edits.\n      hmr: process.env.DISABLE_HMR !== 'true',\n      // Disable file watching when DISABLE_HMR is true to save CPU during agent edits.\n      watch: process.env.DISABLE_HMR === 'true' ? null : {},\n    },\n  };\n});\n",
  "index.html": "<!doctype html>\n<html lang=\"ru\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>PixiTS Oscilloscope & Web Serial Adjuster</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.tsx\"></script>\n  </body>\n</html>\n\n",
  "metadata.json": "{\n  \"name\": \"Web Serial & PixiJS Oscilloscope\",\n  \"description\": \"Real-time Web Serial and PixiJS signal oscilloscope and channel adjuster with multi-channel rendering, Modbus RTU, ring buffer archive, and interactive cursors.\",\n  \"requestFramePermissions\": [],\n  \"majorCapabilities\": [\"MAJOR_CAPABILITY_SERVER_SIDE_GEMINI_API\"]\n}\n",
  "src/main.ts": "// src/main.ts\n\nimport './styles/oscilloscope.css';\nimport { Oscilloscope } from './Oscilloscope';\n\nconsole.log('Oscilloscope starting...');\n\nconst oscilloscope = new Oscilloscope();\noscilloscope.initialize();\n",
  "src/main.tsx": "// src/main.tsx\n\nimport './styles/oscilloscope.css';\nimport { Oscilloscope } from './Oscilloscope';\n\nconsole.log('Oscilloscope starting...');\n\ndocument.addEventListener('DOMContentLoaded', () => {\n    const oscilloscope = new Oscilloscope();\n    oscilloscope.initialize();\n});\n\n// Immediate initialization if DOM is already loaded\nif (document.readyState === 'complete' || document.readyState === 'interactive') {\n    const oscilloscope = new Oscilloscope();\n    oscilloscope.initialize();\n}\n",
  "src/Oscilloscope.ts": "// src/Oscilloscope.ts\n\nimport { Channel } from './core/Channel';\nimport { Archive } from './core/Archive';\nimport { Recorder } from './core/Recorder';\nimport { Settings } from './config/Settings';\nimport { DEVICE_PRESETS } from './config/DeviceModels';\nimport { Serial } from './comm/Serial';\nimport { Table } from './ui/Table';\nimport { Toolbar } from './ui/Toolbar';\nimport { Resizer } from './ui/Resizer';\nimport { Layout } from './ui/Layout';\nimport { SignalGenModal } from './ui/SignalGenModal';\nimport { Renderer } from './graphics/Renderer';\nimport { PixiView } from './graphics/PixiView';\n\nexport class Oscilloscope {\n    private settings: Settings;\n    private archive: Archive;\n    private recorder: Recorder;\n    private serial: Serial;\n    private table!: Table;\n    private toolbar!: Toolbar;\n    private resizer!: Resizer;\n    private renderer!: Renderer;\n\n    private channels: Channel[] = [];\n    private pixiViews: Map<string, PixiView> = new Map();\n    private isRunning: boolean = false;\n    private lastFrameTime: number = 0;\n    private signalGenModal!: SignalGenModal;\n\n    constructor() {\n        this.settings = new Settings();\n        this.archive = new Archive(50000);\n        this.recorder = new Recorder(this.archive);\n        this.serial = new Serial(this.archive);\n        this.renderer = new Renderer(this.settings, this.archive);\n    }\n\n    public async initialize(): Promise<void> {\n        const rootElement = document.getElementById('root') || document.body;\n\n        // Apply initial CSS variables for column widths & row heights\n        this.settings.applyCSSTemplateVariables();\n\n        // Build HTML Layout\n        const layoutElements = Layout.createSkeleton(rootElement);\n\n        // Initialize UI components\n        this.table = new Table(layoutElements.rowsContainer);\n        this.toolbar = new Toolbar(\n            layoutElements.toolbarContainer,\n            this.settings,\n            this.recorder,\n            this.serial\n        );\n        this.toolbar.initialize();\n\n        this.resizer = new Resizer(this.settings, layoutElements.headerContainer);\n        this.resizer.initialize();\n\n        this.signalGenModal = new SignalGenModal(this.serial);\n        this.signalGenModal.onChannelsLoaded((newChannels) => {\n            this.setChannels(newChannels);\n        });\n\n        this.toolbar.onOpenGeneratorModal(() => {\n            this.signalGenModal.open();\n        });\n\n        this.toolbar.onPresetChange((presetId) => {\n            this.loadPreset(presetId);\n        });\n\n        // Listen for export CSV event\n        window.addEventListener('oscilloscope-export-csv', () => {\n            this.recorder.downloadCSV(this.channels);\n        });\n\n        // Load Default Preset (3-Phase Power System)\n        this.loadPreset('3phase_power');\n\n        // Start animation frame update loop\n        this.isRunning = true;\n        this.lastFrameTime = performance.now();\n        requestAnimationFrame((t) => this.loop(t));\n    }\n\n    public setChannels(newChannels: Channel[]): void {\n        // Destroy existing Pixi views\n        this.pixiViews.forEach(view => view.destroy());\n        this.pixiViews.clear();\n        this.table.clear();\n        this.archive.clear();\n\n        this.channels = newChannels;\n        this.serial.setChannels(this.channels);\n\n        // Create Channel Rows and initialize PixiView for each graph container\n        this.channels.forEach(async (channel) => {\n            const row = this.table.addChannel(channel);\n            const graphContainer = row.getGraphContainer();\n\n            const pixiView = new PixiView(graphContainer);\n            await pixiView.init();\n\n            this.pixiViews.set(channel.id, pixiView);\n        });\n    }\n\n    public loadPreset(presetId: string): void {\n        const preset = DEVICE_PRESETS.find(p => p.id === presetId) || DEVICE_PRESETS[0];\n        const newChannels = preset.channels.map(cfg => new Channel(cfg));\n        this.setChannels(newChannels);\n    }\n\n    private loop(now: number): void {\n        if (!this.isRunning) return;\n\n        const dtMs = Math.min(100, now - this.lastFrameTime);\n        this.lastFrameTime = now;\n\n        // 1. Tick simulation generator if Web Serial is inactive\n        this.serial.tickSimulation(dtMs);\n\n        // 2. Update Table row numeric value labels\n        this.table.updateValues();\n\n        // 3. Update Record timer badge in toolbar\n        this.toolbar.updateRecordTimer();\n\n        // 4. Render PixiJS signal waveforms\n        this.channels.forEach(channel => {\n            const view = this.pixiViews.get(channel.id);\n            if (view) {\n                this.renderer.renderChannelGraph(channel, view);\n            }\n        });\n\n        // 5. Update Cursors measurements footer if enabled\n        if (this.settings.enableCursors) {\n            this.updateCursorsFooter();\n        }\n\n        requestAnimationFrame((t) => this.loop(t));\n    }\n\n    private updateCursorsFooter(): void {\n        const curX1 = document.getElementById('cur-x1');\n        const curX2 = document.getElementById('cur-x2');\n        const curDt = document.getElementById('cur-dt');\n        const curFreq = document.getElementById('cur-freq');\n\n        if (curX1 && curX2 && curDt && curFreq) {\n            const x1Pct = this.settings.cursorX1Percent;\n            const x2Pct = this.settings.cursorX2Percent;\n            const dtMs = (Math.abs(x2Pct - x1Pct) / 100) * this.settings.timeWindowMs;\n            const freqHz = dtMs > 0 ? (1000 / dtMs).toFixed(2) : '0';\n\n            curX1.textContent = `${x1Pct.toFixed(1)}%`;\n            curX2.textContent = `${x2Pct.toFixed(1)}%`;\n            curDt.textContent = `${dtMs.toFixed(1)} ms`;\n            curFreq.textContent = `${freqHz} Hz`;\n        }\n    }\n}\n",
  "src/styles/oscilloscope.css": "/* src/styles/oscilloscope.css */\n\n:root {\n    --col-name: 90px;\n    --col-description: 220px;\n    --col-value: 90px;\n    --col-unit: 60px;\n    --row-height: 120px;\n    --bg-main: #0a0a0b;\n    --bg-header: #0f0f11;\n    --bg-card: #141416;\n    --border-color: #2a2a2c;\n    --accent-blue: #00d2ff;\n    --accent-green: #10b981;\n    --accent-red: #ef4444;\n    --accent-amber: #f59e0b;\n    --text-primary: #e0e0e0;\n    --text-muted: #a0a0a5;\n}\n\n* {\n    box-sizing: border-box;\n}\n\nhtml, body {\n    margin: 0;\n    padding: 0;\n    width: 100%;\n    height: 100%;\n    overflow: hidden;\n    background-color: var(--bg-main);\n    color: var(--text-primary);\n    font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;\n    user-select: none;\n}\n\n#oscilloscope {\n    width: 100vw;\n    height: 100vh;\n    display: flex;\n    flex-direction: column;\n    background-color: var(--bg-main);\n}\n\n/* --- Top Toolbar --- */\n#toolbar {\n    height: 48px;\n    background-color: #0f0f11;\n    border-bottom: 1px solid var(--border-color);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 0 16px;\n    gap: 12px;\n    z-index: 10;\n}\n\n.toolbar-group {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n\n.toolbar-title {\n    font-size: 14px;\n    font-weight: 700;\n    letter-spacing: 0.5px;\n    color: #ffffff;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    margin-right: 12px;\n}\n\n.toolbar-btn {\n    height: 32px;\n    padding: 0 12px;\n    background-color: #1a1a1c;\n    border: 1px solid #2a2a2c;\n    border-radius: 4px;\n    color: #e0e0e0;\n    font-size: 12px;\n    font-weight: 600;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    transition: all 0.15s ease;\n}\n\n.toolbar-btn:hover {\n    background-color: #252528;\n    color: #ffffff;\n    border-color: #3a3a3c;\n}\n\n.toolbar-btn.primary {\n    background-color: #00d2ff;\n    border-color: #00d2ff;\n    color: #000000;\n    font-weight: 700;\n}\n\n.toolbar-btn.primary:hover {\n    background-color: #00b8e6;\n    border-color: #00b8e6;\n}\n\n.toolbar-btn.success {\n    background-color: #10b981;\n    border-color: #10b981;\n    color: #ffffff;\n}\n\n.toolbar-btn.success:hover {\n    background-color: #059669;\n}\n\n.toolbar-btn.active {\n    background-color: #00d2ff;\n    border-color: #00d2ff;\n    color: #000000;\n    font-weight: 700;\n}\n\n.toolbar-select {\n    height: 32px;\n    background-color: #1a1a1c;\n    border: 1px solid #2a2a2c;\n    border-radius: 4px;\n    color: #e0e0e0;\n    font-size: 12px;\n    padding: 0 10px;\n    outline: none;\n    cursor: pointer;\n}\n\n.toolbar-select:hover {\n    border-color: #3a3a3c;\n}\n\n.status-badge {\n    padding: 4px 10px;\n    border-radius: 12px;\n    font-size: 11px;\n    font-weight: 600;\n    display: flex;\n    align-items: center;\n    gap: 6px;\n}\n\n.status-badge.connected {\n    background-color: rgba(16, 185, 129, 0.15);\n    color: #34d399;\n    border: 1px solid rgba(16, 185, 129, 0.3);\n}\n\n.status-badge.simulating {\n    background-color: rgba(0, 210, 255, 0.15);\n    color: #00d2ff;\n    border: 1px solid rgba(0, 210, 255, 0.3);\n}\n\n.status-badge.recording {\n    background-color: rgba(239, 68, 68, 0.15);\n    color: #f87171;\n    border: 1px solid rgba(239, 68, 68, 0.3);\n    animation: pulse 1.5s infinite;\n}\n\n@keyframes pulse {\n    0%, 100% { opacity: 1; }\n    50% { opacity: 0.5; }\n}\n\n/* --- Table Header & Columns --- */\n#header {\n    height: 30px;\n    display: grid;\n    grid-template-columns:\n        var(--col-name)\n        var(--col-description)\n        var(--col-value)\n        var(--col-unit)\n        1fr;\n    border-bottom: 1px solid var(--border-color);\n    background-color: #0f0f11;\n    position: relative;\n    user-select: none;\n}\n\n#header > div {\n    padding-left: 10px;\n    display: flex;\n    align-items: center;\n    border-right: 1px solid #2a2a2c;\n    font-size: 11px;\n    font-weight: 700;\n    color: #6a6a6e;\n    text-transform: uppercase;\n    letter-spacing: 0.8px;\n    position: relative;\n}\n\n.col-resizer {\n    position: absolute;\n    right: -3px;\n    top: 0;\n    width: 7px;\n    height: 100%;\n    cursor: col-resize;\n    z-index: 20;\n    background-color: transparent;\n}\n\n.col-resizer:hover, .col-resizer.resizing {\n    background-color: var(--accent-blue);\n}\n\n/* --- Channel Rows Container --- */\n#channelRows {\n    flex: 1;\n    overflow-y: auto;\n    overflow-x: hidden;\n    background-color: var(--bg-main);\n}\n\n.channel-row {\n    display: grid;\n    grid-template-columns:\n        var(--col-name)\n        var(--col-description)\n        var(--col-value)\n        var(--col-unit)\n        1fr;\n    height: var(--row-height);\n    border-bottom: 1px solid #1a1a1c;\n    transition: height 0.05s linear;\n}\n\n.channel-row > div {\n    padding: 0 10px;\n    display: flex;\n    align-items: center;\n    border-right: 1px solid #1a1a1c;\n    font-size: 13px;\n    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n}\n\n.col-name {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n\n.channel-color-indicator {\n    width: 10px;\n    height: 10px;\n    border-radius: 50%;\n    display: inline-block;\n    flex-shrink: 0;\n}\n\n.channel-title {\n    font-weight: 700;\n    color: #e0e0e0;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n}\n\n.col-description {\n    color: #a0a0a5;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n    font-size: 12px;\n}\n\n.col-value {\n    color: #00d2ff;\n    font-weight: 700;\n    font-size: 14px;\n}\n\n.col-unit {\n    color: #6a6a6e;\n    font-size: 12px;\n}\n\n.channel-row .col-graph {\n    padding: 0;\n    position: relative;\n    background-color: #050505;\n    overflow: hidden;\n    width: 100%;\n    height: 100%;\n}\n\n/* --- Row Height Drag Handle --- */\n.row-resizer {\n    height: 5px;\n    background-color: transparent;\n    cursor: row-resize;\n    position: absolute;\n    bottom: 0;\n    left: 0;\n    right: 0;\n    z-index: 15;\n}\n\n.row-resizer:hover, .row-resizer.resizing {\n    background-color: var(--accent-blue);\n}\n\n/* --- Cursors Info Footer --- */\n#footer {\n    height: 28px;\n    background-color: #0f0f11;\n    border-top: 1px solid var(--border-color);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 0 16px;\n    font-size: 11px;\n    font-family: monospace;\n    color: #a0a0a5;\n}\n\n.cursor-stat {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n}\n\n.cursor-stat-item {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n}\n\n.cursor-stat-item span {\n    color: #00d2ff;\n    font-weight: 700;\n}\n\n/* --- Modals / Control Drawers --- */\n.modal-overlay {\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    background-color: rgba(0, 0, 0, 0.8);\n    backdrop-filter: blur(2px);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 100;\n}\n\n.modal-content {\n    background-color: #141416;\n    border: 1px solid #2a2a2c;\n    border-radius: 8px;\n    width: 520px;\n    max-width: 90vw;\n    padding: 24px;\n    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.7);\n}\n\n.modal-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 20px;\n    border-bottom: 1px solid #2a2a2c;\n    padding-bottom: 12px;\n}\n\n.modal-title {\n    font-size: 16px;\n    font-weight: 700;\n    color: #e0e0e0;\n}\n\n.modal-close {\n    background: transparent;\n    border: none;\n    color: #a0a0a5;\n    font-size: 20px;\n    cursor: pointer;\n}\n\n.modal-close:hover {\n    color: #ffffff;\n}\n\n.form-group {\n    margin-bottom: 16px;\n}\n\n.form-group label {\n    display: block;\n    font-size: 12px;\n    font-weight: 600;\n    color: #a0a0a5;\n    margin-bottom: 8px;\n}\n\n.form-input, .form-range {\n    width: 100%;\n    background-color: #0f0f11;\n    border: 1px solid #2a2a2c;\n    border-radius: 4px;\n    color: #e0e0e0;\n    padding: 8px 12px;\n    font-size: 13px;\n}\n\n.form-range {\n    padding: 0;\n    accent-color: #00d2ff;\n}\n\n",
  "src/core/Channel.ts": "// src/core/Channel.ts\n\nexport interface ChannelConfig {\n    id: string;\n    name: string;\n    description: string;\n    value: number | string;\n    unit: string;\n    color?: string;\n    min?: number;\n    max?: number;\n    type?: 'analog' | 'digital';\n    scale?: number;\n    offset?: number;\n    visible?: boolean;\n}\n\nexport class Channel {\n    public readonly id: string;\n    public name: string;\n    public description: string;\n    public value: number | string;\n    public unit: string;\n    public color: string;\n    public min: number;\n    public max: number;\n    public type: 'analog' | 'digital';\n    public scale: number;\n    public offset: number;\n    public visible: boolean;\n\n    constructor(config: ChannelConfig) {\n        this.id = config.id;\n        this.name = config.name;\n        this.description = config.description;\n        this.value = config.value;\n        this.unit = config.unit;\n        this.color = config.color || '#00ff66';\n        this.min = config.min !== undefined ? config.min : -100;\n        this.max = config.max !== undefined ? config.max : 100;\n        this.type = config.type || 'analog';\n        this.scale = config.scale !== undefined ? config.scale : 1.0;\n        this.offset = config.offset !== undefined ? config.offset : 0.0;\n        this.visible = config.visible !== undefined ? config.visible : true;\n    }\n\n    public setValue(value: number | string): void {\n        this.value = value;\n    }\n\n    public getNumericValue(): number {\n        if (typeof this.value === 'number') {\n            return this.value;\n        }\n        const parsed = parseFloat(this.value);\n        return isNaN(parsed) ? 0 : parsed;\n    }\n}\n",
  "src/core/Archive.ts": "// src/core/Archive.ts\n\nexport interface Sample {\n    time: number; // timestamp in ms\n    value: number;\n}\n\nexport class ChannelRingBuffer {\n    public timestamps: Float64Array;\n    public values: Float32Array;\n    public capacity: number;\n    public head: number = 0; // write index\n    public size: number = 0; // current count\n\n    constructor(capacity: number = 50000) {\n        this.capacity = capacity;\n        this.timestamps = new Float64Array(capacity);\n        this.values = new Float32Array(capacity);\n    }\n\n    public push(time: number, value: number): void {\n        this.timestamps[this.head] = time;\n        this.values[this.head] = value;\n        this.head = (this.head + 1) % this.capacity;\n        if (this.size < this.capacity) {\n            this.size++;\n        }\n    }\n\n    public clear(): void {\n        this.head = 0;\n        this.size = 0;\n    }\n\n    /**\n     * Gets samples sorted chronologically\n     */\n    public getRecentSamples(durationMs: number, currentTime?: number): Sample[] {\n        if (this.size === 0) return [];\n\n        const now = currentTime !== undefined ? currentTime : this.timestamps[(this.head - 1 + this.capacity) % this.capacity];\n        const minTime = now - durationMs;\n\n        const result: Sample[] = [];\n        const startIndex = (this.head - this.size + this.capacity) % this.capacity;\n\n        for (let i = 0; i < this.size; i++) {\n            const idx = (startIndex + i) % this.capacity;\n            const t = this.timestamps[idx];\n            if (t >= minTime) {\n                result.push({ time: t, value: this.values[idx] });\n            }\n        }\n\n        return result;\n    }\n\n    public getAllSamples(): Sample[] {\n        if (this.size === 0) return [];\n        const result: Sample[] = [];\n        const startIndex = (this.head - this.size + this.capacity) % this.capacity;\n        for (let i = 0; i < this.size; i++) {\n            const idx = (startIndex + i) % this.capacity;\n            result.push({ time: this.timestamps[idx], value: this.values[idx] });\n        }\n        return result;\n    }\n\n    public getMinMax(durationMs?: number, currentTime?: number): { min: number; max: number } {\n        if (this.size === 0) return { min: -10, max: 10 };\n\n        const now = currentTime !== undefined ? currentTime : this.timestamps[(this.head - 1 + this.capacity) % this.capacity];\n        const minTime = durationMs ? now - durationMs : -Infinity;\n\n        let min = Infinity;\n        let max = -Infinity;\n        let found = false;\n\n        const startIndex = (this.head - this.size + this.capacity) % this.capacity;\n        for (let i = 0; i < this.size; i++) {\n            const idx = (startIndex + i) % this.capacity;\n            const t = this.timestamps[idx];\n            if (t >= minTime) {\n                const v = this.values[idx];\n                if (v < min) min = v;\n                if (v > max) max = v;\n                found = true;\n            }\n        }\n\n        if (!found || min === max) {\n            return { min: min === Infinity ? -10 : min - 10, max: max === -Infinity ? 10 : max + 10 };\n        }\n\n        return { min, max };\n    }\n}\n\nexport class Archive {\n    private buffers: Map<string, ChannelRingBuffer> = new Map();\n    private capacityPerChannel: number;\n\n    constructor(capacityPerChannel: number = 50000) {\n        this.capacityPerChannel = capacityPerChannel;\n    }\n\n    public getOrCreateBuffer(channelId: string): ChannelRingBuffer {\n        let buffer = this.buffers.get(channelId);\n        if (!buffer) {\n            buffer = new ChannelRingBuffer(this.capacityPerChannel);\n            this.buffers.set(channelId, buffer);\n        }\n        return buffer;\n    }\n\n    public addSample(channelId: string, time: number, value: number): void {\n        const buffer = this.getOrCreateBuffer(channelId);\n        buffer.push(time, value);\n    }\n\n    public getRecentSamples(channelId: string, durationMs: number, currentTime?: number): Sample[] {\n        const buffer = this.buffers.get(channelId);\n        if (!buffer) return [];\n        return buffer.getRecentSamples(durationMs, currentTime);\n    }\n\n    public getAllSamples(channelId: string): Sample[] {\n        const buffer = this.buffers.get(channelId);\n        if (!buffer) return [];\n        return buffer.getAllSamples();\n    }\n\n    public getMinMax(channelId: string, durationMs?: number, currentTime?: number): { min: number; max: number } {\n        const buffer = this.buffers.get(channelId);\n        if (!buffer) return { min: -10, max: 10 };\n        return buffer.getMinMax(durationMs, currentTime);\n    }\n\n    public clear(): void {\n        this.buffers.forEach(b => b.clear());\n    }\n}\n",
  "src/core/Recorder.ts": "// src/core/Recorder.ts\n\nimport { Archive } from './Archive';\nimport { Channel } from './Channel';\n\nexport type RecordState = 'idle' | 'recording' | 'paused';\n\nexport class Recorder {\n    private state: RecordState = 'idle';\n    private startTime: number = 0;\n    private pauseTime: number = 0;\n    private totalPausedDuration: number = 0;\n    private archive: Archive;\n\n    constructor(archive: Archive) {\n        this.archive = archive;\n    }\n\n    public start(): void {\n        this.state = 'recording';\n        this.startTime = Date.now();\n        this.totalPausedDuration = 0;\n    }\n\n    public pause(): void {\n        if (this.state === 'recording') {\n            this.state = 'paused';\n            this.pauseTime = Date.now();\n        }\n    }\n\n    public resume(): void {\n        if (this.state === 'paused') {\n            this.totalPausedDuration += (Date.now() - this.pauseTime);\n            this.state = 'recording';\n        }\n    }\n\n    public stop(): void {\n        this.state = 'idle';\n    }\n\n    public getState(): RecordState {\n        return this.state;\n    }\n\n    public getElapsedMs(): number {\n        if (this.state === 'idle') return 0;\n        if (this.state === 'paused') {\n            return this.pauseTime - this.startTime - this.totalPausedDuration;\n        }\n        return Date.now() - this.startTime - this.totalPausedDuration;\n    }\n\n    public exportCSV(channels: Channel[]): string {\n        const lines: string[] = [];\n\n        // Header\n        const header = ['Time_ms', ...channels.map(c => `\"${c.name} (${c.unit})\"` )].join(',');\n        lines.push(header);\n\n        if (channels.length === 0) return lines.join('\\n');\n\n        // Extract all samples per channel\n        const samplesMap = new Map<string, { time: number; value: number }[]>();\n        let maxLen = 0;\n        channels.forEach(ch => {\n            const samples = this.archive.getAllSamples(ch.id);\n            samplesMap.set(ch.id, samples);\n            if (samples.length > maxLen) maxLen = samples.length;\n        });\n\n        // Combine into rows\n        const firstChSamples = samplesMap.get(channels[0].id) || [];\n        for (let i = 0; i < firstChSamples.length; i++) {\n            const rowTime = firstChSamples[i].time;\n            const rowValues = channels.map(ch => {\n                const sList = samplesMap.get(ch.id) || [];\n                const item = sList[i];\n                return item !== undefined ? item.value.toFixed(4) : '';\n            });\n            lines.push([rowTime.toFixed(0), ...rowValues].join(','));\n        }\n\n        return lines.join('\\n');\n    }\n\n    public downloadCSV(channels: Channel[], filename: string = 'oscilloscope_record.csv'): void {\n        const csvContent = this.exportCSV(channels);\n        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });\n        const url = URL.createObjectURL(blob);\n        const link = document.createElement('a');\n        link.setAttribute('href', url);\n        link.setAttribute('download', filename);\n        document.body.appendChild(link);\n        link.click();\n        document.body.removeChild(link);\n    }\n}\n",
  "src/config/Settings.ts": "// src/config/Settings.ts\n\nexport interface ColumnWidths {\n    name: number;\n    description: number;\n    value: number;\n    unit: number;\n}\n\nexport class Settings {\n    public columnWidths: ColumnWidths = {\n        name: 90,\n        description: 220,\n        value: 90,\n        unit: 60,\n    };\n\n    public rowHeight: number = 120; // height in px of each channel row\n    public timeWindowMs: number = 2000; // total duration visible on screen (ms) (2s default)\n    public showGrid: boolean = true;\n    public gridDivisionsX: number = 10;\n    public gridDivisionsY: number = 4;\n    public autoScale: boolean = true;\n    \n    // Cursors\n    public enableCursors: boolean = false;\n    public cursorX1Percent: number = 25; // % of graph width\n    public cursorX2Percent: number = 75; // % of graph width\n\n    // Color theme\n    public backgroundColor: string = '#050505';\n    public gridColor: string = '#1f293d';\n    public textColor: string = '#94a3b8';\n\n    // Timebase options in ms (100ms, 200ms, 500ms, 1s, 2s, 5s, 10s, 20s)\n    public availableTimeWindows: number[] = [200, 500, 1000, 2000, 5000, 10000, 20000];\n\n    public updateColumnWidth(column: keyof ColumnWidths, width: number): void {\n        this.columnWidths[column] = Math.max(30, width);\n        this.applyCSSTemplateVariables();\n    }\n\n    public setRowHeight(height: number): void {\n        this.rowHeight = Math.max(50, height);\n        document.documentElement.style.setProperty('--row-height', `${this.rowHeight}px`);\n    }\n\n    public applyCSSTemplateVariables(): void {\n        document.documentElement.style.setProperty('--col-name', `${this.columnWidths.name}px`);\n        document.documentElement.style.setProperty('--col-description', `${this.columnWidths.description}px`);\n        document.documentElement.style.setProperty('--col-value', `${this.columnWidths.value}px`);\n        document.documentElement.style.setProperty('--col-unit', `${this.columnWidths.unit}px`);\n        document.documentElement.style.setProperty('--row-height', `${this.rowHeight}px`);\n    }\n}\n",
  "src/config/IniParser.ts": "// src/config/IniParser.ts\n\nimport { ChannelConfig } from '../core/Channel';\n\nexport interface ParsedIni {\n    device?: {\n        name?: string;\n        baudRate?: number;\n        protocol?: string;\n    };\n    channels: ChannelConfig[];\n}\n\nexport class IniParser {\n    public static parse(content: string): ParsedIni {\n        const lines = content.split(/\\r?\\n/);\n        const result: ParsedIni = {\n            device: {},\n            channels: []\n        };\n\n        let currentSection = '';\n        let currentChannel: Partial<ChannelConfig> | null = null;\n\n        for (let line of lines) {\n            line = line.trim();\n            if (!line || line.startsWith(';') || line.startsWith('#')) {\n                continue; // Skip comments and empty lines\n            }\n\n            // Section header\n            if (line.startsWith('[') && line.endsWith(']')) {\n                if (currentChannel && currentChannel.id && currentChannel.name) {\n                    result.channels.push(this.completeChannel(currentChannel));\n                    currentChannel = null;\n                }\n\n                currentSection = line.substring(1, line.length - 1).trim();\n\n                if (currentSection.startsWith('CHANNEL_') || currentSection.startsWith('CH_')) {\n                    currentChannel = { id: currentSection.toLowerCase() };\n                }\n                continue;\n            }\n\n            const eqIdx = line.indexOf('=');\n            if (eqIdx === -1) continue;\n\n            const key = line.substring(0, eqIdx).trim().toLowerCase();\n            const val = line.substring(eqIdx + 1).trim().replace(/^[\"']|[\"']$/g, '');\n\n            if (currentSection.toLowerCase() === 'device') {\n                if (key === 'name') result.device!.name = val;\n                if (key === 'baudrate') result.device!.baudRate = parseInt(val, 10);\n                if (key === 'protocol') result.device!.protocol = val;\n            } else if (currentChannel) {\n                if (key === 'id') currentChannel.id = val;\n                if (key === 'name') currentChannel.name = val;\n                if (key === 'description' || key === 'desc') currentChannel.description = val;\n                if (key === 'unit') currentChannel.unit = val;\n                if (key === 'value') currentChannel.value = isNaN(Number(val)) ? val : Number(val);\n                if (key === 'color') currentChannel.color = val;\n                if (key === 'min') currentChannel.min = parseFloat(val);\n                if (key === 'max') currentChannel.max = parseFloat(val);\n                if (key === 'type') currentChannel.type = val === 'digital' ? 'digital' : 'analog';\n            }\n        }\n\n        if (currentChannel && currentChannel.id && currentChannel.name) {\n            result.channels.push(this.completeChannel(currentChannel));\n        }\n\n        return result;\n    }\n\n    private static completeChannel(ch: Partial<ChannelConfig>): ChannelConfig {\n        return {\n            id: ch.id || `ch_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`,\n            name: ch.name || 'Channel',\n            description: ch.description || '',\n            value: ch.value !== undefined ? ch.value : 0,\n            unit: ch.unit || '',\n            color: ch.color || '#00ff66',\n            min: ch.min !== undefined ? ch.min : -100,\n            max: ch.max !== undefined ? ch.max : 100,\n            type: ch.type || 'analog'\n        };\n    }\n\n    public static stringify(iniData: ParsedIni): string {\n        let out = `[DEVICE]\\n`;\n        out += `name=${iniData.device?.name || 'Oscilloscope Device'}\\n`;\n        out += `baudRate=${iniData.device?.baudRate || 115200}\\n`;\n        out += `protocol=${iniData.device?.protocol || 'ModbusRTU'}\\n\\n`;\n\n        iniData.channels.forEach((ch, idx) => {\n            out += `[CHANNEL_${idx + 1}]\\n`;\n            out += `id=${ch.id}\\n`;\n            out += `name=${ch.name}\\n`;\n            out += `description=${ch.description}\\n`;\n            out += `unit=${ch.unit}\\n`;\n            out += `color=${ch.color}\\n`;\n            out += `min=${ch.min}\\n`;\n            out += `max=${ch.max}\\n`;\n            out += `type=${ch.type}\\n\\n`;\n        });\n\n        return out;\n    }\n}\n",
  "src/config/DeviceModels.ts": "// src/config/DeviceModels.ts\n\nimport { ChannelConfig } from '../core/Channel';\n\nexport interface DevicePreset {\n    id: string;\n    name: string;\n    description: string;\n    baudRate: number;\n    channels: ChannelConfig[];\n}\n\nexport const DEVICE_PRESETS: DevicePreset[] = [\n    {\n        id: '3phase_power',\n        name: '3-Phase Power System (IA, IB, IC, UA, UB, UC)',\n        description: 'Standard 3-phase electrical motor & inverter monitoring',\n        baudRate: 115200,\n        channels: [\n            { id: 'ch_ia', name: 'IA', description: 'Phase A Current', value: 12.54, unit: 'A', color: '#ff3366', min: -30, max: 30, type: 'analog' },\n            { id: 'ch_ib', name: 'IB', description: 'Phase B Current', value: -6.27, unit: 'A', color: '#33ccff', min: -30, max: 30, type: 'analog' },\n            { id: 'ch_ic', name: 'IC', description: 'Phase C Current', value: -6.27, unit: 'A', color: '#ffcc00', min: -30, max: 30, type: 'analog' },\n            { id: 'ch_ua', name: 'UA', description: 'Phase A Voltage', value: 220.5, unit: 'V', color: '#00ff66', min: -350, max: 350, type: 'analog' },\n            { id: 'ch_ub', name: 'UB', description: 'Phase B Voltage', value: -110.2, unit: 'V', color: '#ff66cc', min: -350, max: 350, type: 'analog' },\n            { id: 'ch_uc', name: 'UC', description: 'Phase C Voltage', value: -110.2, unit: 'V', color: '#a855f7', min: -350, max: 350, type: 'analog' },\n            { id: 'ch_pwr_ok', name: 'PWR_OK', description: 'Grid Power Good Status', value: 1, unit: 'FLAG', color: '#22c55e', min: 0, max: 1, type: 'digital' },\n            { id: 'ch_trip', name: 'TRIP', description: 'Overcurrent Relay Trip', value: 0, unit: 'FLAG', color: '#ef4444', min: 0, max: 1, type: 'digital' },\n        ]\n    },\n    {\n        id: 'hvac_sensors',\n        name: 'HVAC & Environmental Sensors',\n        description: 'Multi-channel temperature, humidity, pressure & fan control',\n        baudRate: 9600,\n        channels: [\n            { id: 'ch_temp1', name: 'TEMP_IN', description: 'Indoor Temperature', value: 23.4, unit: '°C', color: '#f97316', min: 0, max: 50, type: 'analog' },\n            { id: 'ch_temp2', name: 'TEMP_OUT', description: 'Outdoor Temperature', value: 14.8, unit: '°C', color: '#06b6d4', min: -20, max: 50, type: 'analog' },\n            { id: 'ch_hum', name: 'HUMID', description: 'Relative Humidity', value: 45.2, unit: '%', color: '#3b82f6', min: 0, max: 100, type: 'analog' },\n            { id: 'ch_press', name: 'PRESS', description: 'Barometric Pressure', value: 1013.2, unit: 'hPa', color: '#8b5cf6', min: 900, max: 1100, type: 'analog' },\n            { id: 'ch_fan', name: 'FAN_STATE', description: 'Air Blower Relay', value: 1, unit: 'STATE', color: '#10b981', min: 0, max: 1, type: 'digital' }\n        ]\n    },\n    {\n        id: 'ecg_medical',\n        name: 'Bio-Signal / Heart Rate Monitoring',\n        description: 'High-frequency analog biosignals (ECG & Pulse Ox)',\n        baudRate: 57600,\n        channels: [\n            { id: 'ch_ecg', name: 'ECG_LEAD1', description: 'Electrocardiogram Lead I', value: 0.12, unit: 'mV', color: '#10b981', min: -2.5, max: 2.5, type: 'analog' },\n            { id: 'ch_resp', name: 'RESP', description: 'Respiration Waveform', value: 12.0, unit: 'BPM', color: '#06b6d4', min: 0, max: 30, type: 'analog' },\n            { id: 'ch_spo2', name: 'SpO2', description: 'Blood Oxygen Level', value: 98.5, unit: '%', color: '#f43f5e', min: 80, max: 100, type: 'analog' },\n            { id: 'ch_pacing', name: 'PACE_PULSE', description: 'Pacemaker Detect Event', value: 0, unit: 'TRIG', color: '#eab308', min: 0, max: 1, type: 'digital' }\n        ]\n    }\n];\n",
  "src/comm/Modbus.ts": "// src/comm/Modbus.ts\n\nexport class Modbus {\n    /**\n     * Calculates Modbus RTU CRC16 (Polynomial 0xA001)\n     */\n    public static calculateCRC(buffer: Uint8Array, length?: number): number {\n        let crc = 0xFFFF;\n        const len = length !== undefined ? length : buffer.length;\n\n        for (let pos = 0; pos < len; pos++) {\n            crc ^= buffer[pos];\n            for (let i = 8; i !== 0; i--) {\n                if ((crc & 0x0001) !== 0) {\n                    crc >>= 1;\n                    crc ^= 0xA001;\n                } else {\n                    crc >>= 1;\n                }\n            }\n        }\n        return crc;\n    }\n\n    /**\n     * Builds a Modbus RTU Read Request frame (FC 03 or FC 04)\n     */\n    public static createReadRequest(slaveAddr: number, functionCode: number, startAddr: number, count: number): Uint8Array {\n        const frame = new Uint8Array(8);\n        frame[0] = slaveAddr;\n        frame[1] = functionCode; // 3 or 4\n        frame[2] = (startAddr >> 8) & 0xFF;\n        frame[3] = startAddr & 0xFF;\n        frame[4] = (count >> 8) & 0xFF;\n        frame[5] = count & 0xFF;\n\n        const crc = this.calculateCRC(frame, 6);\n        frame[6] = crc & 0xFF;        // Low byte\n        frame[7] = (crc >> 8) & 0xFF; // High byte\n\n        return frame;\n    }\n\n    /**\n     * Parses a Modbus RTU Read Response frame\n     */\n    public static parseReadResponse(buffer: Uint8Array): { slaveAddr: number; functionCode: number; registers: number[] } | null {\n        if (buffer.length < 5) return null;\n\n        const slaveAddr = buffer[0];\n        const functionCode = buffer[1];\n        const byteCount = buffer[2];\n\n        if (buffer.length < 3 + byteCount + 2) return null; // Frame incomplete\n\n        // Verify CRC\n        const receivedCRC = buffer[3 + byteCount] | (buffer[3 + byteCount + 1] << 8);\n        const calculatedCRC = this.calculateCRC(buffer, 3 + byteCount);\n\n        if (receivedCRC !== calculatedCRC) {\n            console.warn('Modbus CRC check failed!');\n            return null;\n        }\n\n        const registers: number[] = [];\n        for (let i = 0; i < byteCount; i += 2) {\n            const high = buffer[3 + i];\n            const low = buffer[3 + i + 1];\n            // 16-bit signed integer conversion\n            let raw = (high << 8) | low;\n            if (raw & 0x8000) {\n                raw = raw - 0x10000;\n            }\n            registers.push(raw);\n        }\n\n        return { slaveAddr, functionCode, registers };\n    }\n}\n",
  "src/comm/Serial.ts": "// src/comm/Serial.ts\n\nimport { Channel } from '../core/Channel';\nimport { Archive } from '../core/Archive';\nimport { Modbus } from './Modbus';\n\nexport type SerialState = 'disconnected' | 'connecting' | 'connected' | 'simulating' | 'error';\n\nexport interface SignalGenParams {\n    frequency: number;  // Base signal frequency in Hz (e.g., 50 Hz)\n    noiseLevel: number; // Random noise amplitude (0 to 10)\n    harmonics: boolean; // Add 3rd/5th harmonics\n    phaseShift: boolean;// Enable 120-degree 3-phase shift\n}\n\nexport class Serial {\n    private state: SerialState = 'simulating';\n    private port: any = null;\n    private reader: any = null;\n    private baudRate: number = 115200;\n    private archive: Archive;\n    private channels: Channel[] = [];\n    private stateChangeCallbacks: ((state: SerialState, msg?: string) => void)[] = [];\n\n    // Generator settings\n    public simParams: SignalGenParams = {\n        frequency: 50,\n        noiseLevel: 0.5,\n        harmonics: true,\n        phaseShift: true\n    };\n\n    private simTimeMs: number = 0;\n\n    constructor(archive: Archive) {\n        this.archive = archive;\n    }\n\n    public setChannels(channels: Channel[]): void {\n        this.channels = channels;\n    }\n\n    public onStateChange(cb: (state: SerialState, msg?: string) => void): void {\n        this.stateChangeCallbacks.push(cb);\n    }\n\n    private setState(state: SerialState, msg?: string): void {\n        this.state = state;\n        this.stateChangeCallbacks.forEach(cb => cb(state, msg));\n    }\n\n    public getState(): SerialState {\n        return this.state;\n    }\n\n    public isWebSerialSupported(): boolean {\n        return 'serial' in navigator;\n    }\n\n    /**\n     * Connects to hardware serial port via Web Serial API\n     */\n    public async connect(baudRate: number = 115200): Promise<boolean> {\n        this.baudRate = baudRate;\n        if (!this.isWebSerialSupported()) {\n            this.setState('simulating', 'Web Serial API is not supported in this browser environment. Using Signal Simulator.');\n            return false;\n        }\n\n        try {\n            this.setState('connecting', 'Requesting serial port permission...');\n            const navSerial = (navigator as any).serial;\n            this.port = await navSerial.requestPort();\n            await this.port.open({ baudRate: this.baudRate });\n\n            this.setState('connected', `Connected via Serial Port @ ${this.baudRate} baud.`);\n            this.startReading();\n            return true;\n        } catch (err: any) {\n            console.warn('Web Serial connection failed or cancelled:', err);\n            this.setState('simulating', `Serial port connection not established (${err.message || 'Cancelled'}). Using Simulator.`);\n            return false;\n        }\n    }\n\n    public async disconnect(): Promise<void> {\n        try {\n            if (this.reader) {\n                await this.reader.cancel();\n                this.reader.releaseLock();\n                this.reader = null;\n            }\n            if (this.port) {\n                await this.port.close();\n                this.port = null;\n            }\n        } catch (e) {\n            console.error('Error closing serial port:', e);\n        }\n        this.setState('simulating', 'Serial port disconnected. Switched to Simulation Mode.');\n    }\n\n    private async startReading(): Promise<void> {\n        if (!this.port || !this.port.readable) return;\n\n        try {\n            while (this.port.readable && this.state === 'connected') {\n                this.reader = this.port.readable.getReader();\n                try {\n                    while (true) {\n                        const { value, done } = await this.reader.read();\n                        if (done) break;\n                        if (value) {\n                            this.processIncomingBytes(value);\n                        }\n                    }\n                } catch (readErr) {\n                    console.error('Serial stream read error:', readErr);\n                } finally {\n                    this.reader.releaseLock();\n                }\n            }\n        } catch (err) {\n            console.error('Port reading loop failed:', err);\n            this.setState('error', 'Serial communication error');\n        }\n    }\n\n    private rxBuffer: number[] = [];\n    private processIncomingBytes(data: Uint8Array): void {\n        for (let i = 0; i < data.length; i++) {\n            this.rxBuffer.push(data[i]);\n        }\n\n        // Try parsing Modbus RTU frames or line-delimited ASCII values\n        if (this.rxBuffer.length >= 7) {\n            const buf = new Uint8Array(this.rxBuffer);\n            const modbusRes = Modbus.parseReadResponse(buf);\n            if (modbusRes) {\n                const now = Date.now();\n                modbusRes.registers.forEach((regValue, idx) => {\n                    if (idx < this.channels.length) {\n                        const ch = this.channels[idx];\n                        ch.setValue(regValue);\n                        this.archive.addSample(ch.id, now, regValue);\n                    }\n                });\n                this.rxBuffer = [];\n                return;\n            }\n        }\n\n        // Keep buffer trimmed\n        if (this.rxBuffer.length > 512) {\n            this.rxBuffer = this.rxBuffer.slice(-256);\n        }\n    }\n\n    /**\n     * Updates simulation generators on each frame ticker tick\n     */\n    public tickSimulation(dtMs: number): void {\n        if (this.state !== 'simulating' && this.state !== 'disconnected') {\n            return;\n        }\n\n        this.simTimeMs += dtMs;\n        const now = Date.now();\n        const t = this.simTimeMs / 1000;\n        const freq = this.simParams.frequency;\n        const noise = this.simParams.noiseLevel;\n\n        this.channels.forEach((ch, idx) => {\n            let val = 0;\n            const phaseShift = this.simParams.phaseShift ? (idx % 3) * ((2 * Math.PI) / 3) : 0;\n            const omega = 2 * Math.PI * freq;\n\n            if (ch.type === 'digital') {\n                // Digital signal (0 or 1 clock wave)\n                const pulsePeriod = 1.0 / Math.max(0.1, freq / 10);\n                const isHigh = Math.sin(omega * 0.2 * t + phaseShift) > 0;\n                val = isHigh ? 1 : 0;\n            } else {\n                // Analog signal simulation (Sine, harmonics, modulation)\n                let baseWave = Math.sin(omega * t + phaseShift);\n\n                if (this.simParams.harmonics) {\n                    baseWave += 0.2 * Math.sin(3 * omega * t) + 0.1 * Math.sin(5 * omega * t);\n                }\n\n                // Add amplitude scaling based on channel max\n                const amp = (ch.max - ch.min) * 0.4;\n                const mid = (ch.max + ch.min) / 2;\n\n                // Add random noise component\n                const noiseVal = (Math.random() - 0.5) * noise;\n\n                val = mid + baseWave * amp + noiseVal;\n            }\n\n            const roundedVal = Math.round(val * 100) / 100;\n            ch.setValue(roundedVal);\n            this.archive.addSample(ch.id, now, roundedVal);\n        });\n    }\n}\n",
  "src/graphics/PixiView.ts": "// src/graphics/PixiView.ts\n\nimport { Application, Container, Graphics } from 'pixi.js';\n\nexport interface ViewportBounds {\n    width: number;\n    height: number;\n}\n\nexport class PixiView {\n    public app: Application;\n    public stage: Container;\n    public gridGraphics: Graphics;\n    public waveGraphics: Graphics;\n    public cursorGraphics: Graphics;\n    public containerElement: HTMLElement;\n    private initialized: boolean = false;\n    private resizeObserver: ResizeObserver | null = null;\n    public bounds: ViewportBounds = { width: 300, height: 120 };\n\n    constructor(containerElement: HTMLElement) {\n        this.containerElement = containerElement;\n        this.app = new Application();\n        this.stage = new Container();\n        this.gridGraphics = new Graphics();\n        this.waveGraphics = new Graphics();\n        this.cursorGraphics = new Graphics();\n\n        this.stage.addChild(this.gridGraphics);\n        this.stage.addChild(this.waveGraphics);\n        this.stage.addChild(this.cursorGraphics);\n    }\n\n    public async init(): Promise<void> {\n        if (this.initialized) return;\n\n        const rect = this.containerElement.getBoundingClientRect();\n        const width = Math.max(50, Math.floor(rect.width || 400));\n        const height = Math.max(30, Math.floor(rect.height || 120));\n        this.bounds = { width, height };\n\n        await this.app.init({\n            width,\n            height,\n            backgroundColor: 0x050505,\n            antialias: true,\n            autoDensity: true,\n            resolution: window.devicePixelRatio || 1,\n        });\n\n        // Attach Pixi canvas to HTML graph container\n        const canvas = this.app.canvas as HTMLCanvasElement;\n        canvas.style.width = '100%';\n        canvas.style.height = '100%';\n        canvas.style.display = 'block';\n\n        // Clear existing children in container and append canvas\n        this.containerElement.innerHTML = '';\n        this.containerElement.appendChild(canvas);\n\n        this.app.stage.addChild(this.stage);\n\n        // Setup resize observer\n        this.resizeObserver = new ResizeObserver((entries) => {\n            for (let entry of entries) {\n                const w = Math.max(50, Math.floor(entry.contentRect.width));\n                const h = Math.max(30, Math.floor(entry.contentRect.height));\n                if (w !== this.bounds.width || h !== this.bounds.height) {\n                    this.resize(w, h);\n                }\n            }\n        });\n        this.resizeObserver.observe(this.containerElement);\n\n        this.initialized = true;\n    }\n\n    public resize(width: number, height: number): void {\n        this.bounds = { width, height };\n        if (this.app && this.app.renderer) {\n            this.app.renderer.resize(width, height);\n        }\n    }\n\n    public destroy(): void {\n        if (this.resizeObserver) {\n            this.resizeObserver.disconnect();\n            this.resizeObserver = null;\n        }\n        if (this.app) {\n            this.app.destroy(true, { children: true, texture: true });\n        }\n    }\n}\n",
  "src/graphics/Renderer.ts": "// src/graphics/Renderer.ts\n\nimport { Color } from 'pixi.js';\nimport { Channel } from '../core/Channel';\nimport { Archive, Sample } from '../core/Archive';\nimport { Settings } from '../config/Settings';\nimport { PixiView } from './PixiView';\n\nexport class Renderer {\n    private settings: Settings;\n    private archive: Archive;\n\n    constructor(settings: Settings, archive: Archive) {\n        this.settings = settings;\n        this.archive = archive;\n    }\n\n    /**\n     * Renders background grid, signal waveform, and cursors for a given channel row\n     */\n    public renderChannelGraph(channel: Channel, view: PixiView): void {\n        const { width, height } = view.bounds;\n        if (width <= 0 || height <= 0) return;\n\n        // 1. Render Grid\n        this.renderGrid(view, width, height);\n\n        // 2. Fetch recent signal samples from Archive\n        const now = Date.now();\n        const duration = this.settings.timeWindowMs;\n        const samples = this.archive.getRecentSamples(channel.id, duration, now);\n\n        // 3. Render Waveform\n        if (samples.length > 0) {\n            if (channel.type === 'digital') {\n                this.renderDigitalWaveform(channel, samples, view, width, height, now, duration);\n            } else {\n                this.renderAnalogWaveform(channel, samples, view, width, height, now, duration);\n            }\n        } else {\n            view.waveGraphics.clear();\n        }\n\n        // 4. Render Cursors if enabled\n        if (this.settings.enableCursors) {\n            this.renderCursors(view, width, height);\n        } else {\n            view.cursorGraphics.clear();\n        }\n    }\n\n    private renderGrid(view: PixiView, width: number, height: number): void {\n        const g = view.gridGraphics;\n        g.clear();\n\n        if (!this.settings.showGrid) return;\n\n        const gridColor = new Color(this.settings.gridColor).toNumber();\n        const divX = this.settings.gridDivisionsX;\n        const divY = this.settings.gridDivisionsY;\n\n        // Vertical division lines (Time axis)\n        const stepX = width / divX;\n        for (let i = 1; i < divX; i++) {\n            const x = Math.floor(i * stepX);\n            g.moveTo(x, 0);\n            g.lineTo(x, height);\n            g.stroke({ width: 1, color: gridColor, alpha: 0.4 });\n        }\n\n        // Horizontal division lines (Amplitude axis)\n        const stepY = height / divY;\n        for (let j = 1; j < divY; j++) {\n            const y = Math.floor(j * stepY);\n            g.moveTo(0, y);\n            g.lineTo(width, y);\n            g.stroke({ width: 1, color: gridColor, alpha: 0.4 });\n        }\n\n        // Center zero axis dashed line\n        const centerY = Math.floor(height / 2);\n        g.moveTo(0, centerY);\n        g.lineTo(width, centerY);\n        g.stroke({ width: 1, color: gridColor, alpha: 0.8 });\n    }\n\n    private renderAnalogWaveform(\n        channel: Channel,\n        samples: Sample[],\n        view: PixiView,\n        width: number,\n        height: number,\n        currentTime: number,\n        duration: number\n    ): void {\n        const g = view.waveGraphics;\n        g.clear();\n\n        if (samples.length < 2) return;\n\n        // Determine Vertical Range (min / max)\n        let min = channel.min;\n        let max = channel.max;\n\n        if (this.settings.autoScale) {\n            const range = this.archive.getMinMax(channel.id, duration, currentTime);\n            if (range.min !== range.max) {\n                // Add 10% margin top and bottom\n                const margin = (range.max - range.min) * 0.1 || 1;\n                min = range.min - margin;\n                max = range.max + margin;\n            }\n        }\n\n        const vRange = max - min || 1;\n        const startTime = currentTime - duration;\n        const colorNum = new Color(channel.color).toNumber();\n\n        // Map time to X pixel, value to Y pixel\n        const getX = (t: number) => ((t - startTime) / duration) * width;\n        const getY = (val: number) => height - ((val - min) / vRange) * height;\n\n        g.moveTo(getX(samples[0].time), getY(samples[0].value));\n\n        for (let i = 1; i < samples.length; i++) {\n            const x = getX(samples[i].time);\n            const y = getY(samples[i].value);\n            g.lineTo(x, y);\n        }\n\n        // Glow stroke + sharp line\n        g.stroke({ width: 2, color: colorNum, alpha: 0.95 });\n    }\n\n    private renderDigitalWaveform(\n        channel: Channel,\n        samples: Sample[],\n        view: PixiView,\n        width: number,\n        height: number,\n        currentTime: number,\n        duration: number\n    ): void {\n        const g = view.waveGraphics;\n        g.clear();\n\n        if (samples.length < 2) return;\n\n        const startTime = currentTime - duration;\n        const colorNum = new Color(channel.color).toNumber();\n\n        const getX = (t: number) => ((t - startTime) / duration) * width;\n        const highY = height * 0.2; // High state line\n        const lowY = height * 0.8;  // Low state line\n\n        const getY = (v: number) => (v >= 0.5 ? highY : lowY);\n\n        let prevX = getX(samples[0].time);\n        let prevY = getY(samples[0].value);\n\n        g.moveTo(prevX, prevY);\n\n        for (let i = 1; i < samples.length; i++) {\n            const currentX = getX(samples[i].time);\n            const currentY = getY(samples[i].value);\n\n            // Step transition: Horizontal then Vertical\n            g.lineTo(currentX, prevY);\n            g.lineTo(currentX, currentY);\n\n            prevX = currentX;\n            prevY = currentY;\n        }\n\n        g.stroke({ width: 2, color: colorNum, alpha: 1.0 });\n    }\n\n    private renderCursors(view: PixiView, width: number, height: number): void {\n        const g = view.cursorGraphics;\n        g.clear();\n\n        const x1 = (this.settings.cursorX1Percent / 100) * width;\n        const x2 = (this.settings.cursorX2Percent / 100) * width;\n\n        // Cursor 1 (Cyan line)\n        g.moveTo(x1, 0);\n        g.lineTo(x1, height);\n        g.stroke({ width: 1.5, color: 0x06b6d4, alpha: 0.9 });\n\n        // Cursor 2 (Amber line)\n        g.moveTo(x2, 0);\n        g.lineTo(x2, height);\n        g.stroke({ width: 1.5, color: 0xf59e0b, alpha: 0.9 });\n    }\n}\n",
  "src/ui/Table.ts": "// src/ui/Table.ts\n\nimport { Channel } from '../core/Channel';\nimport { ChannelRow } from './ChannelRow';\n\nexport class Table {\n    private readonly container: HTMLElement;\n    private readonly rows: Map<string, ChannelRow> = new Map();\n\n    constructor(container: HTMLElement) {\n        this.container = container;\n    }\n\n    public addChannel(channel: Channel): ChannelRow {\n        // If row already exists, update or return\n        let row = this.rows.get(channel.id);\n        if (row) return row;\n\n        row = new ChannelRow(channel);\n        row.attach(this.container);\n        this.rows.set(channel.id, row);\n        return row;\n    }\n\n    public removeChannel(channelId: string): void {\n        const row = this.rows.get(channelId);\n        if (row) {\n            row.remove();\n            this.rows.delete(channelId);\n        }\n    }\n\n    public getRow(channelId: string): ChannelRow | undefined {\n        return this.rows.get(channelId);\n    }\n\n    public getAllRows(): ChannelRow[] {\n        return Array.from(this.rows.values());\n    }\n\n    public updateValues(): void {\n        this.rows.forEach(row => row.updateValue());\n    }\n\n    public clear(): void {\n        this.rows.forEach(row => row.remove());\n        this.rows.clear();\n        this.container.innerHTML = '';\n    }\n}\n",
  "src/ui/ChannelRow.ts": "// src/ui/ChannelRow.ts\n\nimport { Channel } from '../core/Channel';\n\nexport class ChannelRow {\n    private readonly element: HTMLDivElement;\n    private readonly nameElement: HTMLDivElement;\n    private readonly descriptionElement: HTMLDivElement;\n    private readonly valueElement: HTMLDivElement;\n    private readonly unitElement: HTMLDivElement;\n    private readonly graphElement: HTMLDivElement;\n    private readonly colorIndicator: HTMLSpanElement;\n\n    constructor(public readonly channel: Channel) {\n        this.element = document.createElement('div');\n        this.element.className = 'channel-row';\n        this.element.dataset.channelId = channel.id;\n\n        // Name Column\n        this.nameElement = document.createElement('div');\n        this.nameElement.className = 'col-name';\n\n        this.colorIndicator = document.createElement('span');\n        this.colorIndicator.className = 'channel-color-indicator';\n        this.colorIndicator.style.backgroundColor = channel.color;\n\n        const titleSpan = document.createElement('span');\n        titleSpan.className = 'channel-title';\n        titleSpan.textContent = channel.name;\n\n        this.nameElement.append(this.colorIndicator, titleSpan);\n\n        // Description Column\n        this.descriptionElement = document.createElement('div');\n        this.descriptionElement.className = 'col-description';\n        this.descriptionElement.textContent = channel.description;\n\n        // Value Column\n        this.valueElement = document.createElement('div');\n        this.valueElement.className = 'col-value';\n        this.valueElement.textContent = String(channel.value);\n\n        // Unit Column\n        this.unitElement = document.createElement('div');\n        this.unitElement.className = 'col-unit';\n        this.unitElement.textContent = channel.unit;\n\n        // PixiJS Canvas Graph Column\n        this.graphElement = document.createElement('div');\n        this.graphElement.className = 'col-graph';\n\n        this.element.append(\n            this.nameElement,\n            this.descriptionElement,\n            this.valueElement,\n            this.unitElement,\n            this.graphElement\n        );\n    }\n\n    public attach(parent: HTMLElement): void {\n        parent.appendChild(this.element);\n    }\n\n    public remove(): void {\n        if (this.element.parentElement) {\n            this.element.parentElement.removeChild(this.element);\n        }\n    }\n\n    public updateValue(): void {\n        const val = this.channel.value;\n        if (typeof val === 'number') {\n            this.valueElement.textContent = val % 1 === 0 ? val.toString() : val.toFixed(2);\n        } else {\n            this.valueElement.textContent = String(val);\n        }\n    }\n\n    public getGraphContainer(): HTMLElement {\n        return this.graphElement;\n    }\n\n    public getElement(): HTMLElement {\n        return this.element;\n    }\n}\n",
  "src/ui/Resizer.ts": "// src/ui/Resizer.ts\n\nimport { Settings, ColumnWidths } from '../config/Settings';\n\nexport class Resizer {\n    private settings: Settings;\n    private headerElement: HTMLElement;\n    private isResizing: boolean = false;\n\n    constructor(settings: Settings, headerElement: HTMLElement) {\n        this.settings = settings;\n        this.headerElement = headerElement;\n    }\n\n    public initialize(): void {\n        const columns: { name: keyof ColumnWidths; selector: string }[] = [\n            { name: 'name', selector: '.col-name' },\n            { name: 'description', selector: '.col-description' },\n            { name: 'value', selector: '.col-value' },\n            { name: 'unit', selector: '.col-unit' }\n        ];\n\n        columns.forEach(col => {\n            const headerCol = this.headerElement.querySelector(col.selector) as HTMLElement;\n            if (headerCol) {\n                const handle = document.createElement('div');\n                handle.className = 'col-resizer';\n                headerCol.appendChild(handle);\n\n                this.bindColumnResize(handle, col.name);\n            }\n        });\n    }\n\n    private bindColumnResize(handle: HTMLElement, colKey: keyof ColumnWidths): void {\n        handle.addEventListener('mousedown', (e: MouseEvent) => {\n            e.preventDefault();\n            this.isResizing = true;\n            handle.classList.add('resizing');\n\n            const startX = e.clientX;\n            const startWidth = this.settings.columnWidths[colKey];\n\n            const onMouseMove = (moveEvent: MouseEvent) => {\n                if (!this.isResizing) return;\n                const deltaX = moveEvent.clientX - startX;\n                const newWidth = Math.max(35, startWidth + deltaX);\n                this.settings.updateColumnWidth(colKey, newWidth);\n            };\n\n            const onMouseUp = () => {\n                this.isResizing = false;\n                handle.classList.remove('resizing');\n                window.removeEventListener('mousemove', onMouseMove);\n                window.removeEventListener('mouseup', onMouseUp);\n            };\n\n            window.addEventListener('mousemove', onMouseMove);\n            window.addEventListener('mouseup', onMouseUp);\n        });\n    }\n}\n",
  "src/ui/Toolbar.ts": "// src/ui/Toolbar.ts\n\nimport { Settings } from '../config/Settings';\nimport { Recorder } from '../core/Recorder';\nimport { Serial } from '../comm/Serial';\nimport { DEVICE_PRESETS } from '../config/DeviceModels';\n\nexport class Toolbar {\n    private container: HTMLElement;\n    private settings: Settings;\n    private recorder: Recorder;\n    private serial: Serial;\n\n    private connectBtn!: HTMLButtonElement;\n    private baudSelect!: HTMLSelectElement;\n    private presetSelect!: HTMLSelectElement;\n    private recordBtn!: HTMLButtonElement;\n    private timebaseSelect!: HTMLSelectElement;\n    private autoscaleBtn!: HTMLButtonElement;\n    private cursorBtn!: HTMLButtonElement;\n    private generatorBtn!: HTMLButtonElement;\n    private exportBtn!: HTMLButtonElement;\n    private statusBadge!: HTMLSpanElement;\n\n    private onPresetChangeCallback?: (presetId: string) => void;\n    private onOpenGeneratorModalCallback?: () => void;\n\n    constructor(\n        container: HTMLElement,\n        settings: Settings,\n        recorder: Recorder,\n        serial: Serial\n    ) {\n        this.container = container;\n        this.settings = settings;\n        this.recorder = recorder;\n        this.serial = serial;\n    }\n\n    public onPresetChange(cb: (presetId: string) => void): void {\n        this.onPresetChangeCallback = cb;\n    }\n\n    public onOpenGeneratorModal(cb: () => void): void {\n        this.onOpenGeneratorModalCallback = cb;\n    }\n\n    public initialize(): void {\n        this.container.innerHTML = '';\n\n        // Group 1: Connection & Presets\n        const groupLeft = document.createElement('div');\n        groupLeft.className = 'toolbar-group';\n\n        const title = document.createElement('div');\n        title.className = 'toolbar-title';\n        title.innerHTML = `⚡ PixiTS Oscilloscope`;\n\n        // Connect Button\n        this.connectBtn = document.createElement('button');\n        this.connectBtn.className = 'toolbar-btn primary';\n        this.connectBtn.innerHTML = `🔌 Web Serial`;\n        this.connectBtn.addEventListener('click', () => this.handleConnectClick());\n\n        // Baud Select\n        this.baudSelect = document.createElement('select');\n        this.baudSelect.className = 'toolbar-select';\n        [9600, 19200, 38400, 57600, 115200, 230400].forEach(baud => {\n            const opt = document.createElement('option');\n            opt.value = String(baud);\n            opt.textContent = `${baud} Baud`;\n            if (baud === 115200) opt.selected = true;\n            this.baudSelect.appendChild(opt);\n        });\n\n        // Device Presets Select\n        this.presetSelect = document.createElement('select');\n        this.presetSelect.className = 'toolbar-select';\n        DEVICE_PRESETS.forEach(preset => {\n            const opt = document.createElement('option');\n            opt.value = preset.id;\n            opt.textContent = `📋 Preset: ${preset.name.split(' ')[0]}`;\n            this.presetSelect.appendChild(opt);\n        });\n        this.presetSelect.addEventListener('change', (e) => {\n            const val = (e.target as HTMLSelectElement).value;\n            if (this.onPresetChangeCallback) this.onPresetChangeCallback(val);\n        });\n\n        groupLeft.append(title, this.connectBtn, this.baudSelect, this.presetSelect);\n\n        // Group 2: Controls (Timebase, Auto-Scale, Cursors, Signal Gen)\n        const groupCenter = document.createElement('div');\n        groupCenter.className = 'toolbar-group';\n\n        // Timebase Select\n        const timebaseLabel = document.createElement('span');\n        timebaseLabel.style.fontSize = '12px';\n        timebaseLabel.style.color = '#94a3b8';\n        timebaseLabel.textContent = 'Timebase:';\n\n        this.timebaseSelect = document.createElement('select');\n        this.timebaseSelect.className = 'toolbar-select';\n        [\n            { label: '200 ms', val: 200 },\n            { label: '500 ms', val: 500 },\n            { label: '1.0 sec', val: 1000 },\n            { label: '2.0 sec', val: 2000 },\n            { label: '5.0 sec', val: 5000 },\n            { label: '10 sec', val: 10000 }\n        ].forEach(t => {\n            const opt = document.createElement('option');\n            opt.value = String(t.val);\n            opt.textContent = t.label;\n            if (t.val === this.settings.timeWindowMs) opt.selected = true;\n            this.timebaseSelect.appendChild(opt);\n        });\n        this.timebaseSelect.addEventListener('change', (e) => {\n            this.settings.timeWindowMs = parseInt((e.target as HTMLSelectElement).value, 10);\n        });\n\n        // Autoscale Toggle\n        this.autoscaleBtn = document.createElement('button');\n        this.autoscaleBtn.className = `toolbar-btn ${this.settings.autoScale ? 'active' : ''}`;\n        this.autoscaleBtn.innerHTML = `📐 Auto-Scale`;\n        this.autoscaleBtn.addEventListener('click', () => {\n            this.settings.autoScale = !this.settings.autoScale;\n            this.autoscaleBtn.classList.toggle('active', this.settings.autoScale);\n        });\n\n        // Cursors Toggle\n        this.cursorBtn = document.createElement('button');\n        this.cursorBtn.className = `toolbar-btn ${this.settings.enableCursors ? 'active' : ''}`;\n        this.cursorBtn.innerHTML = `📏 Cursors`;\n        this.cursorBtn.addEventListener('click', () => {\n            this.settings.enableCursors = !this.settings.enableCursors;\n            this.cursorBtn.classList.toggle('active', this.settings.enableCursors);\n            const footer = document.getElementById('footer');\n            if (footer) footer.style.display = this.settings.enableCursors ? 'flex' : 'none';\n        });\n\n        // Signal Gen Controls Button\n        this.generatorBtn = document.createElement('button');\n        this.generatorBtn.className = 'toolbar-btn';\n        this.generatorBtn.innerHTML = `🌊 Signal Gen`;\n        this.generatorBtn.addEventListener('click', () => {\n            if (this.onOpenGeneratorModalCallback) this.onOpenGeneratorModalCallback();\n        });\n\n        groupCenter.append(timebaseLabel, this.timebaseSelect, this.autoscaleBtn, this.cursorBtn, this.generatorBtn);\n\n        // Group 3: Recording & Export\n        const groupRight = document.createElement('div');\n        groupRight.className = 'toolbar-group';\n\n        this.recordBtn = document.createElement('button');\n        this.recordBtn.className = 'toolbar-btn success';\n        this.recordBtn.innerHTML = `🔴 Record`;\n        this.recordBtn.addEventListener('click', () => this.handleRecordClick());\n\n        this.exportBtn = document.createElement('button');\n        this.exportBtn.className = 'toolbar-btn';\n        this.exportBtn.innerHTML = `💾 Export CSV`;\n        this.exportBtn.addEventListener('click', () => {\n            window.dispatchEvent(new CustomEvent('oscilloscope-export-csv'));\n        });\n\n        this.statusBadge = document.createElement('span');\n        this.statusBadge.className = 'status-badge simulating';\n        this.statusBadge.textContent = 'SIMULATOR ACTIVE';\n\n        groupRight.append(this.recordBtn, this.exportBtn, this.statusBadge);\n\n        this.container.append(groupLeft, groupCenter, groupRight);\n\n        // Listen for serial state changes\n        this.serial.onStateChange((state, msg) => {\n            if (state === 'connected') {\n                this.statusBadge.className = 'status-badge connected';\n                this.statusBadge.textContent = 'SERIAL CONNECTED';\n                this.connectBtn.innerHTML = `🔌 Disconnect`;\n            } else if (state === 'simulating') {\n                this.statusBadge.className = 'status-badge simulating';\n                this.statusBadge.textContent = 'SIMULATOR ACTIVE';\n                this.connectBtn.innerHTML = `🔌 Web Serial`;\n            }\n        });\n    }\n\n    private async handleConnectClick(): Promise<void> {\n        if (this.serial.getState() === 'connected') {\n            await this.serial.disconnect();\n        } else {\n            const baud = parseInt(this.baudSelect.value, 10);\n            await this.serial.connect(baud);\n        }\n    }\n\n    private handleRecordClick(): void {\n        const state = this.recorder.getState();\n        if (state === 'idle') {\n            this.recorder.start();\n            this.recordBtn.innerHTML = `⏸️ Recording...`;\n            this.recordBtn.classList.remove('success');\n            this.recordBtn.classList.add('primary');\n            this.statusBadge.className = 'status-badge recording';\n            this.statusBadge.textContent = 'REC 0.0s';\n        } else if (state === 'recording') {\n            this.recorder.stop();\n            this.recordBtn.innerHTML = `🔴 Record`;\n            this.recordBtn.classList.remove('primary');\n            this.recordBtn.classList.add('success');\n            this.statusBadge.className = this.serial.getState() === 'connected' ? 'status-badge connected' : 'status-badge simulating';\n            this.statusBadge.textContent = this.serial.getState() === 'connected' ? 'SERIAL CONNECTED' : 'SIMULATOR ACTIVE';\n        }\n    }\n\n    public updateRecordTimer(): void {\n        if (this.recorder.getState() === 'recording') {\n            const sec = (this.recorder.getElapsedMs() / 1000).toFixed(1);\n            this.statusBadge.textContent = `REC ${sec}s`;\n        }\n    }\n}\n",
  "src/ui/Layout.ts": "// src/ui/Layout.ts\n\nexport class Layout {\n    public static createSkeleton(rootElement: HTMLElement): {\n        toolbarContainer: HTMLElement;\n        headerContainer: HTMLElement;\n        rowsContainer: HTMLElement;\n        footerContainer: HTMLElement;\n    } {\n        rootElement.innerHTML = `\n            <div id=\"oscilloscope\">\n                <div id=\"toolbar\"></div>\n                <div id=\"header\">\n                    <div class=\"col-name\">Name</div>\n                    <div class=\"col-description\">Description</div>\n                    <div class=\"col-value\">Value</div>\n                    <div class=\"col-unit\">Unit</div>\n                    <div class=\"col-graph\">Graph Waveform (PixiJS)</div>\n                </div>\n                <div id=\"channelRows\"></div>\n                <div id=\"footer\" style=\"display: none;\">\n                    <div class=\"cursor-stat\">\n                        <div class=\"cursor-stat-item\">Cursor X1: <span id=\"cur-x1\">25.0%</span></div>\n                        <div class=\"cursor-stat-item\">Cursor X2: <span id=\"cur-x2\">75.0%</span></div>\n                        <div class=\"cursor-stat-item\">Δt: <span id=\"cur-dt\">1000 ms</span></div>\n                        <div class=\"cursor-stat-item\">Frequency f: <span id=\"cur-freq\">1.00 Hz</span></div>\n                    </div>\n                    <div>Drag graph with mouse wheel to zoom | Cursors enabled</div>\n                </div>\n            </div>\n        `;\n\n        return {\n            toolbarContainer: rootElement.querySelector('#toolbar') as HTMLElement,\n            headerContainer: rootElement.querySelector('#header') as HTMLElement,\n            rowsContainer: rootElement.querySelector('#channelRows') as HTMLElement,\n            footerContainer: rootElement.querySelector('#footer') as HTMLElement,\n        };\n    }\n}\n",
  "src/ui/SignalGenModal.ts": "// src/ui/SignalGenModal.ts\n\nimport { Serial } from '../comm/Serial';\nimport { IniParser } from '../config/IniParser';\nimport { Channel } from '../core/Channel';\n\nexport class SignalGenModal {\n    private serial: Serial;\n    private modalOverlay: HTMLElement | null = null;\n    private onChannelsLoadedCallback?: (channels: Channel[]) => void;\n\n    constructor(serial: Serial) {\n        this.serial = serial;\n    }\n\n    public onChannelsLoaded(cb: (channels: Channel[]) => void): void {\n        this.onChannelsLoadedCallback = cb;\n    }\n\n    public open(): void {\n        if (this.modalOverlay) return;\n\n        this.modalOverlay = document.createElement('div');\n        this.modalOverlay.className = 'modal-overlay';\n        this.modalOverlay.innerHTML = `\n            <div class=\"modal-content\">\n                <div class=\"modal-header\">\n                    <span class=\"modal-title\">🌊 Signal Generator & Configuration</span>\n                    <button class=\"modal-close\" id=\"modal-close-btn\">&times;</button>\n                </div>\n                \n                <div class=\"form-group\">\n                    <label>Signal Frequency: <span id=\"freq-val\">${this.serial.simParams.frequency}</span> Hz</label>\n                    <input type=\"range\" class=\"form-range\" id=\"freq-slider\" min=\"1\" max=\"200\" value=\"${this.serial.simParams.frequency}\">\n                </div>\n\n                <div class=\"form-group\">\n                    <label>Noise Level: <span id=\"noise-val\">${this.serial.simParams.noiseLevel}</span></label>\n                    <input type=\"range\" class=\"form-range\" id=\"noise-slider\" min=\"0\" max=\"10\" step=\"0.1\" value=\"${this.serial.simParams.noiseLevel}\">\n                </div>\n\n                <div class=\"form-group\" style=\"display: flex; gap: 16px; margin-top: 12px;\">\n                    <label style=\"display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n                        <input type=\"checkbox\" id=\"harmonics-chk\" ${this.serial.simParams.harmonics ? 'checked' : ''}>\n                        Add Harmonics (3rd & 5th)\n                    </label>\n                    <label style=\"display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n                        <input type=\"checkbox\" id=\"phase-chk\" ${this.serial.simParams.phaseShift ? 'checked' : ''}>\n                        120° 3-Phase Shift\n                    </label>\n                </div>\n\n                <hr style=\"border: 0; border-top: 1px solid #334155; margin: 16px 0;\">\n\n                <div class=\"form-group\">\n                    <label>Import INI Configuration File</label>\n                    <input type=\"file\" id=\"ini-file-input\" accept=\".ini,.txt\" style=\"font-size: 12px; color: #cbd5e1;\">\n                </div>\n\n                <div style=\"display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px;\">\n                    <button class=\"toolbar-btn primary\" id=\"modal-done-btn\">Done</button>\n                </div>\n            </div>\n        `;\n\n        document.body.appendChild(this.modalOverlay);\n\n        // Bind events\n        const closeBtn = this.modalOverlay.querySelector('#modal-close-btn');\n        const doneBtn = this.modalOverlay.querySelector('#modal-done-btn');\n        const freqSlider = this.modalOverlay.querySelector('#freq-slider') as HTMLInputElement;\n        const noiseSlider = this.modalOverlay.querySelector('#noise-slider') as HTMLInputElement;\n        const harmonicsChk = this.modalOverlay.querySelector('#harmonics-chk') as HTMLInputElement;\n        const phaseChk = this.modalOverlay.querySelector('#phase-chk') as HTMLInputElement;\n        const fileInput = this.modalOverlay.querySelector('#ini-file-input') as HTMLInputElement;\n\n        closeBtn?.addEventListener('click', () => this.close());\n        doneBtn?.addEventListener('click', () => this.close());\n\n        freqSlider?.addEventListener('input', (e) => {\n            const val = parseFloat((e.target as HTMLInputElement).value);\n            this.serial.simParams.frequency = val;\n            const freqValSpan = this.modalOverlay?.querySelector('#freq-val');\n            if (freqValSpan) freqValSpan.textContent = String(val);\n        });\n\n        noiseSlider?.addEventListener('input', (e) => {\n            const val = parseFloat((e.target as HTMLInputElement).value);\n            this.serial.simParams.noiseLevel = val;\n            const noiseValSpan = this.modalOverlay?.querySelector('#noise-val');\n            if (noiseValSpan) noiseValSpan.textContent = String(val);\n        });\n\n        harmonicsChk?.addEventListener('change', (e) => {\n            this.serial.simParams.harmonics = (e.target as HTMLInputElement).checked;\n        });\n\n        phaseChk?.addEventListener('change', (e) => {\n            this.serial.simParams.phaseShift = (e.target as HTMLInputElement).checked;\n        });\n\n        fileInput?.addEventListener('change', (e) => {\n            const file = (e.target as HTMLInputElement).files?.[0];\n            if (!file) return;\n\n            const reader = new FileReader();\n            reader.onload = (event) => {\n                const text = event.target?.result as string;\n                if (text) {\n                    const parsed = IniParser.parse(text);\n                    if (parsed.channels.length > 0 && this.onChannelsLoadedCallback) {\n                        const newChannels = parsed.channels.map(cfg => new Channel(cfg));\n                        this.onChannelsLoadedCallback(newChannels);\n                        this.close();\n                    }\n                }\n            };\n            reader.readAsText(file);\n        });\n    }\n\n    public close(): void {\n        if (this.modalOverlay && this.modalOverlay.parentElement) {\n            this.modalOverlay.parentElement.removeChild(this.modalOverlay);\n            this.modalOverlay = null;\n        }\n    }\n}\n"
};

Object.entries(bundle).forEach(([filePath, content]) => {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(filePath, content, "utf8");
  console.log("Created:", filePath);
});

console.log("\nDone! Run: npm install && npm run dev");
